INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Na América portuguesa, extensas propriedades costeiras concentravam a produção de açúcar para o mercado europeu. O trabalho era realizado predominantemente por pessoas escravizadas.','Esse modelo econômico colonial se caracterizava principalmente por','[{"key":"A","text":"pequenas propriedades voltadas exclusivamente ao consumo familiar."},{"key":"B","text":"latifúndio, monocultura de exportação e trabalho escravizado."},{"key":"C","text":"produção industrial descentralizada e trabalho assalariado universal."},{"key":"D","text":"reforma agrária e distribuição igualitária das terras."},{"key":"E","text":"ausência de vínculos comerciais com o mercado externo."}]'::jsonb,'B','A economia açucareira colonial articulava grandes propriedades, produção especializada para exportação e escravização. Essa organização atendia aos interesses da colonização portuguesa.','["Identifique quem controlava a terra, para onde ia o produto e qual era a força de trabalho."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H01','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-brasil-colonia' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H01');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Durante o período colonial, comunidades formadas por pessoas que escapavam da escravização desenvolveram formas próprias de organização social e defesa, muitas vezes mantendo relações com outros grupos.','A existência dessas comunidades, conhecidas como quilombos, evidencia','[{"key":"A","text":"formas de resistência e construção de autonomia frente ao sistema escravista."},{"key":"B","text":"a aceitação universal da ordem colonial por pessoas escravizadas."},{"key":"C","text":"a inexistência de conflitos sociais na colonização."},{"key":"D","text":"a concessão de cidadania plena pelo governo português."},{"key":"E","text":"a abolição imediata da escravidão em todo o território."}]'::jsonb,'A','Quilombos constituíram formas diversas de resistência à escravização e de organização comunitária. Sua existência contradiz a ideia de passividade diante da ordem colonial.','["Fugir e organizar uma comunidade autônoma é uma forma de quê?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H02','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-brasil-colonia' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H02');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em 1888, a Lei Áurea extinguiu juridicamente a escravidão no Brasil. Entretanto, a população recém-liberta não recebeu, por essa lei, medidas amplas de acesso à terra, escolarização ou trabalho protegido.','O contraste indica que a abolição','[{"key":"A","text":"garantiu por si só a igualdade econômica entre todos os brasileiros."},{"key":"B","text":"impediu a existência de desigualdades raciais no período republicano."},{"key":"C","text":"substituiu imediatamente o trabalho livre pelo trabalho servil."},{"key":"D","text":"não foi acompanhada de políticas suficientes de integração social e econômica."},{"key":"E","text":"eliminou as disputas políticas sobre o acesso à cidadania."}]'::jsonb,'D','A liberdade jurídica foi uma conquista decisiva, mas a ausência de políticas estruturais de inclusão contribuiu para a persistência de desigualdades no pós-abolição.','["Liberdade legal e igualdade de oportunidades são a mesma coisa?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H03','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-brasil-imperio' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H03');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Na Primeira República brasileira, um chefe político regional prometia favores e empregos a moradores em troca de apoio eleitoral, usando sua influência para controlar votos.','A prática descrita é associada ao','[{"key":"A","text":"federalismo parlamentar do Segundo Reinado."},{"key":"B","text":"voto universal secreto assegurado a todos os cidadãos."},{"key":"C","text":"coronelismo e ao chamado voto de cabresto."},{"key":"D","text":"sistema de eleições diretas para todos os cargos coloniais."},{"key":"E","text":"enfraquecimento completo do poder das elites locais."}]'::jsonb,'C','O coronelismo envolvia relações clientelistas e coerção exercidas por lideranças locais, capazes de influenciar o voto durante a Primeira República.','["Repare no controle do voto por uma liderança local."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H04','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-brasil-republica' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H04');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Após duas décadas de ditadura militar, a Constituição brasileira de 1988 ampliou a proteção dos direitos individuais, coletivos e sociais e reforçou mecanismos de participação política.','Nesse contexto, a Constituição de 1988 representa','[{"key":"A","text":"o retorno ao Estado Novo de 1937."},{"key":"B","text":"a supressão do direito ao voto."},{"key":"C","text":"a substituição do Poder Judiciário por autoridades militares."},{"key":"D","text":"a extinção dos direitos sociais."},{"key":"E","text":"um marco da redemocratização e da ampliação da cidadania."}]'::jsonb,'E','Promulgada no processo de redemocratização, a Constituição de 1988 ficou conhecida como Constituição Cidadã por consolidar liberdades e direitos sociais.','["Qual processo político estava em curso após a ditadura?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H05','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-brasil-republica' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H05');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'No século XIX, a expansão das fábricas atraiu trabalhadores para cidades industriais. Muitos enfrentavam longas jornadas, ambientes insalubres e baixa remuneração.','Uma consequência histórica dessas condições foi','[{"key":"A","text":"o fortalecimento das organizações operárias e das reivindicações por direitos trabalhistas."},{"key":"B","text":"a eliminação dos conflitos entre capital e trabalho."},{"key":"C","text":"a universalização imediata de jornadas de oito horas."},{"key":"D","text":"o abandono da produção mecanizada em favor do artesanato."},{"key":"E","text":"o fim dos movimentos de migração campo-cidade."}]'::jsonb,'A','As condições precárias de trabalho na industrialização estimularam associações de trabalhadores, sindicatos e lutas por regulamentação da jornada e proteção social.','["Como os trabalhadores passaram a reagir às condições de trabalho?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H06','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-historia-geral' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H06');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Na segunda metade do século XX, Estados Unidos e União Soviética disputaram influência internacional por meio de propaganda, alianças militares e apoio a governos e grupos em conflitos regionais.','O texto descreve um aspecto característico da','[{"key":"A","text":"expansão marítima ibérica do século XV."},{"key":"B","text":"Guerra Fria, marcada por rivalidade geopolítica e conflitos indiretos."},{"key":"C","text":"Revolução Neolítica, baseada na agricultura."},{"key":"D","text":"unificação política da Europa medieval."},{"key":"E","text":"ausência de disputas ideológicas após 1945."}]'::jsonb,'B','Na Guerra Fria, EUA e URSS competiram por influência política, econômica e militar. Parte da disputa ocorreu por meio de aliados e guerras por procuração, sem guerra direta generalizada entre as superpotências.','["Quais potências protagonizaram a rivalidade bipolar?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H07','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-historia-geral' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H07');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em uma comunidade, a tradição de produzir cerâmica com técnicas transmitidas entre gerações é reconhecida e preservada pelos moradores, junto às histórias ligadas à prática.','Esse exemplo se aproxima do conceito de patrimônio cultural','[{"key":"A","text":"exclusivamente natural, por se referir a rochas e rios."},{"key":"B","text":"apenas arquitetônico, pois depende de edifícios antigos."},{"key":"C","text":"industrial, por exigir produção em larga escala."},{"key":"D","text":"imaterial, relacionado a saberes, práticas e modos de fazer."},{"key":"E","text":"privado, sem vínculo com a memória coletiva."}]'::jsonb,'D','Patrimônio imaterial abrange saberes, celebrações, expressões e modos de fazer transmitidos socialmente. A técnica tradicional e sua memória são elementos culturais.','["O que se preserva é um prédio ou um saber transmitido?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H08','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-historia-cultural' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H08');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Uma criança aprende em casa regras de convivência e, na escola, passa a conhecer normas de participação coletiva, debate e cooperação.','O processo pelo qual indivíduos aprendem valores e comportamentos sociais é chamado de','[{"key":"A","text":"anomia."},{"key":"B","text":"êxodo rural."},{"key":"C","text":"socialização."},{"key":"D","text":"segregação espacial."},{"key":"E","text":"acumulação primitiva."}]'::jsonb,'C','Socialização é a aprendizagem de normas, valores e formas de agir em sociedade, ocorrendo em diferentes instituições, como família, escola e grupos de convivência.','["Pense no aprendizado da vida em sociedade."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H09','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-sociologia' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H09');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Uma política municipal deve ser avaliada não só por sua eficiência, mas também pelo respeito às pessoas atingidas, inclusive grupos socialmente vulneráveis.','A preocupação ética central nesse tipo de avaliação é','[{"key":"A","text":"o reconhecimento da dignidade humana e dos direitos dos envolvidos."},{"key":"B","text":"a garantia de privilégios exclusivos a grupos com maior renda."},{"key":"C","text":"a substituição do debate público por ordens individuais."},{"key":"D","text":"a defesa de que resultados econômicos anulam todos os deveres morais."},{"key":"E","text":"a proibição de qualquer revisão das políticas."}]'::jsonb,'A','A análise ética considera consequências, deveres e respeito à dignidade das pessoas. Eficiência isolada não justifica violar direitos fundamentais.','["Uma política eficiente pode ser considerada boa se violar direitos?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H10','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-filosofia' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H10');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Um país apresenta queda gradual das taxas de mortalidade e de fecundidade. Ao longo das décadas, cresce a proporção de idosos na população.','Essa mudança demográfica aponta para','[{"key":"A","text":"explosão permanente das taxas de natalidade."},{"key":"B","text":"redução obrigatória da expectativa de vida."},{"key":"C","text":"aumento imediato da população rural."},{"key":"D","text":"desaparecimento das necessidades de políticas previdenciárias."},{"key":"E","text":"envelhecimento populacional associado à transição demográfica."}]'::jsonb,'E','Com menos nascimentos e maior sobrevivência, tende a aumentar a participação relativa de idosos. Isso exige planejamento de saúde, previdência e cuidados.','["Como muda a proporção de idosos quando nascem menos crianças?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H11','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-geo-humana' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H11');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em uma região, grandes propriedades ocupam a maior parte das terras agricultáveis, enquanto muitas famílias produtoras possuem áreas pequenas e enfrentam dificuldades de acesso ao crédito.','A situação evidencia','[{"key":"A","text":"a inexistência de desigualdades fundiárias."},{"key":"B","text":"a concentração fundiária e seus impactos sobre a produção e o acesso a recursos."},{"key":"C","text":"a distribuição homogênea da terra entre produtores."},{"key":"D","text":"o desaparecimento de conflitos ligados à posse da terra."},{"key":"E","text":"a impossibilidade de existir agricultura familiar."}]'::jsonb,'B','A concentração fundiária se refere à posse de grandes extensões de terra por poucos proprietários, o que pode produzir desigualdades de acesso a recursos e conflitos no campo.','["Quem detém a maior parte da terra disponível?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H12','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-geo-economica' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H12');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Um bairro substituiu áreas de solo exposto e vegetação por asfalto e concreto. Depois disso, as chuvas intensas passaram a produzir enxurradas mais rápidas.','Uma explicação para o aumento das enxurradas é','[{"key":"A","text":"o aumento da infiltração de água no solo impermeável."},{"key":"B","text":"a diminuição completa do escoamento superficial."},{"key":"C","text":"a impermeabilização do solo, que reduz a infiltração e aumenta o escoamento."},{"key":"D","text":"o desaparecimento da gravidade durante a chuva."},{"key":"E","text":"a formação de lençóis freáticos na superfície asfaltada."}]'::jsonb,'C','Asfalto e concreto dificultam a infiltração da água da chuva; uma parcela maior escoa pela superfície em menor tempo, elevando o risco de alagamentos.','["O que acontece com a água quando o solo não a absorve?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H13','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-meio-ambiente' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H13');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em uma área de floresta tropical, a retirada de vegetação reduz a quantidade de água que volta à atmosfera por transpiração das plantas.','Uma consequência possível desse processo é','[{"key":"A","text":"o aumento automático da umidade em todos os continentes."},{"key":"B","text":"a ausência de alterações no ciclo da água."},{"key":"C","text":"a elevação garantida das chuvas em todas as estações."},{"key":"D","text":"a redução da evapotranspiração, que pode modificar a umidade e o regime de chuvas regional."},{"key":"E","text":"a interrupção definitiva de toda circulação atmosférica."}]'::jsonb,'D','A vegetação participa do ciclo da água pela evapotranspiração. Seu desmatamento pode reduzir fluxos de umidade e afetar o padrão regional de precipitações.','["Qual processo relaciona as plantas ao vapor de água atmosférico?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H14','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-geo-fisica' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H14');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em um mapa cuja escala numérica é 1:100.000, a distância em linha reta entre dois locais mede 3 centímetros.','A distância real aproximada entre esses locais é de','[{"key":"A","text":"30 metros."},{"key":"B","text":"300 metros."},{"key":"C","text":"30 quilômetros."},{"key":"D","text":"300 quilômetros."},{"key":"E","text":"3 quilômetros."}]'::jsonb,'E','Na escala 1:100.000, cada centímetro no mapa corresponde a 100.000 cm na realidade, ou 1 km. Logo, 3 cm representam 3 km.','["100.000 centímetros equivalem a quantos quilômetros?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H15','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-cartografia' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H15');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Uma mensagem viral afirma que determinada medida pública foi revogada, mas não informa data, documento oficial ou fonte confiável. Vários perfis a reproduzem.','Uma atitude adequada para avaliar a confiabilidade da mensagem é','[{"key":"A","text":"verificar a origem, a data e a informação em fontes oficiais e veículos confiáveis antes de compartilhar."},{"key":"B","text":"acreditar no conteúdo porque ele foi encaminhado muitas vezes."},{"key":"C","text":"publicar a mensagem imediatamente para alcançar mais pessoas."},{"key":"D","text":"considerar qualquer postagem anônima mais confiável que documentos públicos."},{"key":"E","text":"ignorar todas as informações que apresentem fontes verificáveis."}]'::jsonb,'A','Checagem de autoria, contexto, data e fontes independentes reduz o risco de compartilhar desinformação. Popularidade de uma postagem não garante veracidade.','["Quantidade de compartilhamentos comprova a verdade de uma notícia?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-H16','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='ch-atualidades' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-H16');
